const NIGERIA_CENTER: LatLng = { lat: 9.082, lng: 8.6753 };

export function getStateCoords(stateName: string): LatLng {
  return STATE_CAPITAL_COORDS[stateName] ?? NIGERIA_CENTER;
}

// Spread `index` of `total` points in a ring around a center point.
// Used for LGA-within-state, ward-within-LGA, and PU-within-ward placement
// where we don't have real sub-state coordinates.
export function ringPoint(center: LatLng, index: number, total: number, radiusDeg: number): LatLng {
  if (total <= 1) return center;
  const angle = (2 * Math.PI * index) / total;
  return {
    lat: center.lat + radiusDeg * Math.sin(angle),
    lng: center.lng + radiusDeg * Math.cos(angle),
  };
}

export const RADIUS_LGA_DEG = 0.35; // spread of LGAs around a state capital
export const RADIUS_WARD_DEG = 0.045; // spread of wards around a flagship LGA center
export const RADIUS_PU_DEG = 0.008; // spread of PUs around a ward center

