// Operational viewport lock for the Kwara-wide Command Center map — NOT a
// surveyed state boundary polygon (same provenance caveat as the LGA-center
// points above). Derived from the real KWARA_LGA_CENTERS extremes (south:
// Oke-Ero 7.98°N, north: Baruten 9.67°N, west: Baruten 3.53°E, east: Patigi
// 5.75°E) with a small pad on most sides. The west pad is deliberately kept
// tight (+0.15° instead of the usual +0.35°): Kwara's entire western edge is
// the international border with Benin Republic (confirmed via Wikipedia),
// and the un-padded statewide map view was drifting far enough west to show
// Benin's OSM base-map tiles — rendered with French place labels, and
// visually reading as "not Kwara" — exactly the two problems reported after
// the Session 3 review. Locking the map's pan/zoom to this box keeps the
// Command Center framed on Kwara State itself.
export const KWARA_STATE_BOUNDS: [LatLng, LatLng] = [
  { lat: 7.6333, lng: 3.3833 }, // southwest corner
  { lat: 10.0167, lng: 6.1 }, // northeast corner
];

// --- Mobilisation Module: simulated GPS check-in ---
// We have no surveyed per-PU coordinates (see note above), so a real
// device-vs-PU distance check isn't possible offline. Instead we simulate a
// plausible "device GPS reading vs. registered PU location" distance,
// deterministic per agent so a rehearsal run matches the live pitch run.
// <100m reads as verified (typical smartphone GPS accuracy at a real PU
// compound); >=100m is flagged for manual review, same as a real
// geofence-based check-in would behave.
export const GPS_VERIFY_THRESHOLD_M = 100;

export function simulateGpsCheckIn(agentId: string): { distanceM: number; verified: boolean } {
  const distanceM = seededInt(agentId + "-gps", 4, 190);
  return { distanceM, verified: distanceM < GPS_VERIFY_THRESHOLD_M };
}
